SELECT
  CASE WHEN (CAST(SUBSTR('2024-02-28', 6, 2) AS BIGINT) = 2) THEN CASE WHEN ((((MOD(CAST(SUBSTR('2024-02-28', 1, 4) AS BIGINT), NULLIF(4, 0))) = 0) AND ((MOD(CAST(SUBSTR('2024-02-28', 1, 4) AS BIGINT), NULLIF(100, 0))) != 0)) OR ((MOD(CAST(SUBSTR('2024-02-28', 1, 4) AS BIGINT), NULLIF(400, 0))) = 0)) THEN 29 ELSE 28 END ELSE (CASE WHEN ((CAST(SUBSTR('2024-02-28', 6, 2) AS BIGINT)) - (1)) < 0 THEN NULL ELSE ELEMENT_AT(ARRAY[31, 0, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31], ((CAST(SUBSTR('2024-02-28', 6, 2) AS BIGINT)) - (1)) + 1) END) END AS n;